create table person (
  id            serial primary key,
  email         text,
  password_hash text,
  full_name     text,
  kind          text,
  credits       numeric(10,2) default 0,
  active        boolean default true,
  created_at    timestamp
);

create table room (
  id       serial primary key,
  name     text,
  capacity integer
);

create table session (
  id                serial primary key,
  room_id           integer references room(id),
  coach_id          integer references person(id),
  discipline        text,
  session_type      text,
  status            text default 'scheduled',
  starts_at         timestamptz,
  ends_at           timestamptz,
  room_fee_credits  numeric(10,2),
  seat_fee_credits  numeric(10,2),
  created_at        timestamptz default now()
);

create table enrolment (
  id               serial primary key,
  session_id       integer references session(id),
  person_id        integer references person(id),
  status           text default 'active',
  credits_charged  numeric(10,2),
  credits_refunded numeric(10,2) default 0,
  enrolled_at      timestamptz,
  cancelled_at     timestamptz
);

create table check_in (
  id            serial primary key,
  enrolment_id  integer references enrolment(id),
  checked_in_at timestamptz
);

create index idx_session_created_discipline_status
  on session (created_at, discipline, status);

